<?= $this->section('scripts') ?><script>
    $(function () {
        var records = <?= json_encode($invoices, JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT) ?>; window.patientPdfRecords = records;
        var activeInvoice = null;
        var escapeHtml = function (value) { return $('<div>').text(value == null ? '' : value).html(); };
        $('.patient-date-filter').datepicker({ format: 'dd-mm-yyyy', autoclose: true, todayHighlight: true, orientation: 'bottom auto', container: '.patient-invoices-page' });
        $(document).on('show.bs.dropdown.patientInvoices', '.patient-invoices-page .dropdown', function () { var dropdown = $(this); var menu = dropdown.children('.dropdown-menu'); if (! menu.length) return; menu.data('patient-dropdown-parent', dropdown).appendTo('body'); });
        $(document).on('hidden.bs.dropdown.patientInvoices', '.patient-invoices-page .dropdown', function () { var dropdown = $(this); var menu = $('body > .dropdown-menu').filter(function () { var parent = $(this).data('patient-dropdown-parent'); return parent && parent.is(dropdown); }).first(); if (menu.length) menu.appendTo(dropdown).removeData('patient-dropdown-parent'); });
        $(document).on('click.patientInvoiceDetails', '.patient-invoice-view', function () {
            var invoice = records.find(function (item) { return Number(item.id) === Number($(this).data('id')); }.bind(this));
            var body = $('#patient-invoice-detail-body');
            var printButton = $('#patient-invoice-print');
            body.html('<div class="patient-modal-loading" role="status"><span class="spinner-border spinner-border-sm mr-2" aria-hidden="true"></span>Loading invoice details…</div>');
            printButton.prop('disabled', true);
            if (! invoice) { body.html('<div class="patient-modal-state patient-modal-state-error" role="alert">Invoice details could not be found.</div>'); return; }
            activeInvoice = invoice;
            var rows = (invoice.items || []).map(function (item) { return '<tr><td data-label="Item">' + escapeHtml(item.description || 'Item unavailable') + '</td><td data-label="Quantity">' + escapeHtml(item.quantity || '—') + '</td><td data-label="Unit price">' + escapeHtml(Number(item.unit_price || 0).toFixed(2)) + '</td><td data-label="Line total">' + escapeHtml(Number(item.line_total || 0).toFixed(2)) + '</td></tr>'; }).join('');
            $('#patient-invoice-detail-title').text('Invoice Details · ' + (invoice.invoice_number || '—'));
            body.html('<section class="patient-modal-section"><h3><i class="bi bi-building mr-2" aria-hidden="true"></i>Clinic and patient</h3><div class="patient-detail-grid"><div><span>Clinic</span><strong>' + escapeHtml(invoice.clinic_name || 'Clinic not recorded') + '<small class="d-block text-muted">' + escapeHtml(invoice.clinic_mobile || invoice.clinic_email || 'Contact not recorded') + '</small></strong></div><div><span>Patient</span><strong>' + escapeHtml(invoice.patient_name || 'Patient') + '<small class="d-block text-muted">' + escapeHtml(invoice.registration_number || '—') + ' · ' + escapeHtml(invoice.patient_mobile || '—') + '</small></strong></div><div class="patient-detail-wide"><span>Invoice</span><strong>' + escapeHtml(invoice.invoice_number || '—') + ' · ' + escapeHtml(invoice.invoice_date_display || '—') + '</strong></div></div></section><section class="patient-modal-section"><h3><i class="bi bi-receipt mr-2" aria-hidden="true"></i>Invoice items</h3><div class="table-responsive patient-invoice-items-wrap"><table class="table table-sm patient-invoice-items"><thead><tr><th>Item</th><th>Quantity</th><th>Unit price</th><th>Line total</th></tr></thead><tbody>' + (rows || '<tr><td colspan="4">No invoice items recorded.</td></tr>') + '</tbody></table></div><div class="patient-invoice-totals"><span>Subtotal <strong>' + escapeHtml(Number(invoice.subtotal || 0).toFixed(2)) + '</strong></span><span>Tax <strong>' + escapeHtml(Number(invoice.tax || 0).toFixed(2)) + '</strong></span><span>Discount <strong>' + escapeHtml(Number(invoice.discount || 0).toFixed(2)) + '</strong></span><span>Total <strong>' + escapeHtml((invoice.currency || 'INR') + ' ' + Number(invoice.total || 0).toFixed(2)) + '</strong></span></div></section><section class="patient-modal-section"><h3><i class="bi bi-credit-card mr-2" aria-hidden="true"></i>Payment</h3><div class="patient-detail-grid"><div><span>Status</span><strong>' + escapeHtml(invoice.payment_status_label || '—') + '</strong></div><div><span>Provider</span><strong>' + escapeHtml(invoice.payment_provider || 'Not recorded') + '</strong></div><div class="patient-detail-wide"><span>Reference</span><strong>' + escapeHtml(invoice.payment_reference || 'Not available') + '</strong></div></div></section><p class="patient-modal-metadata"><i class="fa-solid fa-circle-exclamation mr-1" aria-hidden="true"></i>Created: ' + escapeHtml(invoice.created_at || '—') + '<br>Updated: ' + escapeHtml(invoice.updated_at || '—') + '</p>');
            printButton.prop('disabled', false);
        });
        $('#patient-invoice-print').on('click', function () { if (! activeInvoice) return; var rows = (activeInvoice.items || []).map(function (item) { return '<tr><td>' + escapeHtml(item.description || 'Item unavailable') + '</td><td>' + escapeHtml(item.quantity || '—') + '</td><td>' + escapeHtml(Number(item.unit_price || 0).toFixed(2)) + '</td><td>' + escapeHtml(Number(item.line_total || 0).toFixed(2)) + '</td></tr>'; }).join(''); var printWindow = window.open('', '_blank', 'width=980,height=760'); if (! printWindow) return; var markup = '<!doctype html><html><head><meta charset="utf-8"><title>' + escapeHtml(activeInvoice.invoice_number || 'Invoice') + '</title><style>body{font:12px Arial,sans-serif;color:#1f2940;padding:24px}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{padding:7px;border:1px solid #ccd3df;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#f0f3f8}tr{page-break-inside:avoid}@media print{body{padding:0}}</style></head><body><h1>Invoice ' + escapeHtml(activeInvoice.invoice_number || '—') + '</h1><p>Patient: ' + escapeHtml(activeInvoice.patient_name || 'Patient') + ' · Date: ' + escapeHtml(activeInvoice.invoice_date_display || '—') + '</p><table><thead><tr><th>Item</th><th>Quantity</th><th>Unit price</th><th>Line total</th></tr></thead><tbody>' + rows + '</tbody></table><p>Total: ' + escapeHtml((activeInvoice.currency || 'INR') + ' ' + Number(activeInvoice.total || 0).toFixed(2)) + '<br>Payment: ' + escapeHtml(activeInvoice.payment_status_label || '—') + '</p></body></html>'; printWindow.onload = function () { window.setTimeout(function () { printWindow.focus(); printWindow.print(); printWindow.close(); }, 250); }; printWindow.document.open(); printWindow.document.write(markup); printWindow.document.close(); });
    });
</script><?= $this->endSection() ?>
